#pragma once
#include "core/actor_state.hpp"
#include "core/input_transfer_entries.hpp"
#include "core/palette_effect.hpp"
namespace rolo {
struct GlyphPixelPorts:DisplayPortServices{virtual std::uint16_t read_data_word()=0;};
inline void publish_glyph_pixel(std::uint32_t destination,std::uint16_t x,std::uint16_t y,std::uint16_t ink,GlyphPixelPorts&p){p.control_word(0x8f00);const auto block=std::uint16_t(std::uint16_t(x&0xfff8)*4);destination+=std::uint32_t(std::int32_t(signed_word(block)));if(x&4)destination+=2;const unsigned shift=((~x)&3)*4;const auto shifted=std::uint16_t(ink<<shift);const auto mask=std::uint16_t((std::uint32_t(0xfff0)<<shift)|(shift?std::uint32_t(0xfff0)>>(16-shift):0));const auto row=std::uint16_t(y*4);destination+=std::uint32_t(std::int32_t(signed_word(row)));const auto low=std::uint16_t(destination);const auto read=(std::uint32_t(low&0x3fff)<<16)|(low>>14);p.control_long(read);const auto value=std::uint16_t((p.read_data_word()&mask)|shifted);p.control_long(read|0x40000000);p.data_word(value);}
inline void publish_expanded_glyph(std::span<const std::uint8_t>glyph,DisplayPortState&state,DisplayPortServices&p){if(glyph.size()<32)throw std::out_of_range("Expanded glyph extent");std::uint16_t destination=64;for(unsigned i=0;i<32;++i)for(unsigned nibble:{unsigned(glyph[i]>>4),unsigned(glyph[i]&15)}){fill_display_bytes(std::uint16_t(nibble*0x1111),destination,31,0x40000000,state,p);destination=std::uint16_t(destination+32);}fill_display_bytes(0x7777,32,31,0x40000000,state,p);}
inline void initialize_four_palette_jobs(std::span<PaletteEffect>jobs,std::span<const std::uint16_t>current,std::span<const std::uint16_t>target){if(jobs.size()<4||current.size()<64||target.size()<64)throw std::out_of_range("Four palette jobs extent");for(unsigned i=0;i<4;++i)initialize_palette_effect(jobs[i],current.subspan(i*16,16),target.subspan(i*16,16),0);}
inline std::uint32_t actor_outside_rectangle(const ActorState&a,std::uint16_t left,std::uint16_t right,std::uint16_t top,std::uint16_t bottom){const auto width=signed_word(a.word(36));const auto half=std::uint16_t(width>=0?width/2:-((1-int(width))/2));auto edge=std::uint16_t(a.word(12)-half);if(signed_word(edge)<signed_word(left))return 0xffffffffu;edge=std::uint16_t(edge+half*2);if(signed_word(edge)>signed_word(right))return 0xffffffffu;edge=a.word(16);if(signed_word(edge)>signed_word(bottom))return 0xffffffffu;edge=std::uint16_t(edge-a.word(38));if(signed_word(edge)<signed_word(top))return 0xffffffffu;return 0;}
inline void adjust_actor_vertical_force(ActorState&a,std::uint32_t force){auto direction=a.byte(122);auto speed=direction&128?a.longword(62)+force:a.longword(62)-force;if(speed&0x80000000u){speed=0u-speed;direction=std::uint8_t(0-direction);}if(signed_long(speed)>0xf0000)speed=0xf0000;a.longword(62,speed);a.byte(122,direction);}
}
